class Solution { private fun bfs(start:Int,mask:Int,graph:Array<MutableList<Int>>):IntArray{val distance=IntArray(graph.size){-1};val queue=java.util.ArrayDeque<Int>();queue.add(start);distance[start]=0;var farthest=start;var count=0;while(queue.isNotEmpty()){val node=queue.removeFirst();count++;if(distance[node]>distance[farthest])farthest=node;for(next in graph[node])if(mask and (1 shl next)!=0&&distance[next]<0){distance[next]=distance[node]+1;queue.addLast(next)}};return intArrayOf(farthest,distance[farthest],count)};fun countSubgraphsForEachDiameter(n:Int,edges:Array<IntArray>):IntArray{val graph=Array(n){mutableListOf<Int>()};for(edge in edges){val a=edge[0]-1;val b=edge[1]-1;graph[a].add(b);graph[b].add(a)};val answer=IntArray(n-1);for(mask in 1 until (1 shl n)){val size=Integer.bitCount(mask);if(size<2)continue;val start=Integer.numberOfTrailingZeros(mask);val first=bfs(start,mask,graph);if(first[2]!=size)continue;val diameter=bfs(first[0],mask,graph)[1];answer[diameter-1]++};return answer} }
